let workshopTab='missions',missionId='setup',missionFeedback=null,mathFeedback={};
function missionRecord(){const key=state.business+'/'+missionId;return state.missions[key]||(state.missions[key]={step:0,answers:{}});}
function missionStepsSolved(){return Object.entries(state.missions).reduce((sum,[key,record])=>{const m=MISSIONS.find(m=>key.endsWith('/'+m.id));return sum+(m?m.steps.filter((s,i)=>record.answers?.[i]===s[3]).length:0);},0);}
function workshopPage(){return `${heading('LESS READING. MORE DECISIONS.',U('Saath saath karke seekho.','Learn by doing, step by step.'),U('Ek task choose karo. Har decision ka reason aur next action milega.','Choose a task. Get the reason and next action for every decision.'))}<div class="section-heading"><span class="tag">${esc(t(biz().name))}</span><select id="workshop-business" class="lang" aria-label="Workshop business">${BUSINESSES.map(b=>`<option value="${b.id}" ${b.id===state.business?'selected':''}>${esc(t(b.name))}</option>`).join('')}</select></div><div class="tabs">${[['missions',W('Guided missions','Guided missions')],['tracking',W('Tracking playground','Tracking playground')],['math',W('Khud calculation karo','Calculation drills')],['case',W('Complete campaign case','Complete campaign case')]].map(([id,name])=>`<button data-workshop-tab="${id}" class="${workshopTab===id?'active':''}">${t(name)}</button>`).join('')}</div>${workshopTab==='missions'?missionView():workshopTab==='tracking'?trackingView():workshopTab==='case'?caseView():mathView()}${footer()}`;}
function missionView(){const m=MISSIONS.find(x=>x.id===missionId)||MISSIONS[0],r=missionRecord();r.step=Math.max(0,Math.min(m.steps.length-1,r.step));const s=m.steps[r.step],correct=r.answers[r.step]===s[3];return `<div class="mission-grid"><aside class="card"><div class="eyebrow">CHOOSE YOUR MISSION</div>${MISSIONS.map(x=>`<button class="mission-choice ${x.id===missionId?'active':''}" data-mission="${x.id}"><b>${esc(t(x.name))}</b><span>${esc(t(x.desc))}</span><small>${x.steps.length} ${U('steps','steps')}</small></button>`).join('')}<p>${U('Progress har business ke liye alag save hoti hai.','Progress is saved separately for each business.')}</p></aside><article class="card"><div class="simulation-label">GUIDED PRACTICE · NOT THE GOOGLE INTERFACE</div><div class="section-heading" style="margin:18px 0"><span class="eyebrow" style="margin:0">${U('STEP','STEP')} ${r.step+1} / ${m.steps.length}</span><span class="tag">${m.steps.filter((s,i)=>r.answers[i]===s[3]).length} ${U('solved','solved')}</span></div><div class="progress-track" style="margin-bottom:25px"><div class="progress-fill" style="width:${(r.step+1)/m.steps.length*100}%"></div></div><h2>${esc(t(s[0]))}</h2><div class="example"><div class="label">${U('TUMHARA CONTEXT','YOUR CONTEXT')}</div><p>${esc(t(biz().name))} → ${esc(t(biz().goal))}</p></div><p>${esc(t(s[1]))}</p><div class="quiz-options">${s[2].map((o,i)=>`<button class="option ${r.answers[r.step]===i?(correct?'correct':'wrong'):''}" data-mission-answer="${i}">${String.fromCharCode(65+i)}. ${esc(t(o))}</button>`).join('')}</div>${r.answers[r.step]!==undefined?`<div class="feedback ${correct?'':'error'}" role="status"><b>${correct?U('Bilkul. Ab reason samjho.','Correct. Here is why.'):U('Is decision ko dobara dekho.','Reconsider this decision.')}</b> ${esc(t(s[4]))}</div>${correct?`<div class="next-action"><div class="label">${U('AB ASAL PRACTICE','YOUR NEXT ACTION')}</div><p>${esc(t(s[5]))}</p></div>`:''}`:''}<div class="lesson-nav"><button class="btn light" id="mission-back" ${r.step===0?'disabled':''}>← ${U('Peechay','Back')}</button><button class="btn" id="mission-next" ${!correct?'disabled':''}>${r.step===m.steps.length-1?U('Mission review','Review mission'):U('Agla step','Next step')} →</button></div><div id="mission-summary" aria-live="polite"></div><details class="source-details"><summary>${U('Official guide aur implementation help','Official guide and implementation help')}</summary>${sourceLinks([m.source])}${missionId==='tracking'?`<a class="source-link" href="https://support.google.com/tagmanager/answer/6105160?hl=en" target="_blank" rel="noopener noreferrer">↗ Google Ads conversions in Tag Manager</a>${sourceLinks(['tagsetup','tagtest','consent'])}`:''}</details></article></div>`;}
let sim={trigger:'click',dedupe:false,seen:[],events:[],attempts:0,successes:0,current:null};
function trackingEvent(action){if(action==='reset'){sim={trigger:sim.trigger,dedupe:sim.dedupe,seen:[],events:[],attempts:0,successes:0,current:null};return;}const repeat=action==='repeat';if(repeat&&!sim.current)return;const id=repeat?sim.current:'DEMO-'+String(sim.attempts+1).padStart(3,'0');const success=action!=='invalid';if(!repeat){sim.attempts++;if(success){sim.successes++;sim.current=id;}}const fires=sim.trigger==='click'||success;const duplicate=sim.seen.includes(id);const suppressed=fires&&sim.dedupe&&duplicate;if(fires&&!suppressed)sim.seen.push(id);sim.events.unshift({id,success,fires:fires&&!suppressed,suppressed,repeat});}
function trackingView(){return `<div class="cards"><section class="card"><div class="simulation-label">TEACHING MODEL · NO LIVE TAGS OR DATA SENT</div><h2 style="margin-top:15px">${U('Click hua, lead bani?','A click happened. Was it a lead?')}</h2><p>${U('Yahan koi real form ya customer data nahi. Fake outcomes trigger karke dekho measurement ka design numbers ko kaise badalta hai.','No real form or customer data is used. Trigger fictional outcomes to see how measurement design changes numbers.')}</p><label class="field">${U('Tag kab fire ho?','When should the tag fire?')}<select id="sim-trigger"><option value="click" ${sim.trigger==='click'?'selected':''}>${U('Har submit click par — risky design','Every submit click — risky design')}</option><option value="success" ${sim.trigger==='success'?'selected':''}>${U('Sirf confirmed success par','Only on confirmed success')}</option></select></label><label class="sim-check"><input type="checkbox" id="sim-dedupe" ${sim.dedupe?'checked':''}>${U('Is demo mein same event ID dobara count na karo','In this demo, do not recount the same event ID')}</label><div class="action-row"><button class="btn light" data-sim="invalid">${U('Invalid form try karo','Try invalid form')}</button><button class="btn" data-sim="valid">${U('Nayi successful submission','New successful submission')}</button><button class="btn light" data-sim="repeat" ${!sim.current?'disabled':''}>${U('Wohi success dobara bhejo','Repeat the same success')}</button></div><div class="note" style="margin-top:20px">${U('Is demo ka deduplication rule event ID par based hai. Real purchases mein transaction ID aur real leads mein backend/event design verify karna hota hai. Ye Google tag behavior ki exact copy nahi.','This demo deduplicates by event ID. Real purchases require transaction-ID verification and real leads require suitable backend/event design. This is not an exact model of Google tag behavior.')}</div><button class="text-btn" data-sim="reset" style="margin-top:20px">${U('Demo numbers reset karo','Reset demo numbers')}</button></section><section class="card"><div class="eyebrow">WATCH THE NUMBERS</div><div class="metrics">${metric(U('Valid unique outcomes','Valid unique outcomes'),sim.successes,U('Asal successful submissions','Actual successful submissions'))}${metric(U('Simulated counted events','Simulated counted events'),sim.events.filter(e=>e.fires).length,U('Trigger design ka result','Result of the trigger design'))}</div><h3 style="margin-top:25px">${U('Event log','Event log')}</h3>${sim.events.length?`<ol class="event-log">${sim.events.slice(0,12).map(e=>`<li><span class="event-dot ${e.fires?'fired':''}"></span><div><b>${e.id}</b> · ${e.success?U('success','success'):U('validation fail','validation failed')}${e.repeat?' · repeat':''}<small>${e.suppressed?U('Duplicate roka gaya','Duplicate suppressed'):e.fires?U('Event count hua','Event counted'):U('Event fire nahi hua','Event did not fire')}</small></div></li>`).join('')}</ol>`:`<p>${U('Left side se koi outcome try karo.','Try an outcome using the buttons.')}</p>`}<div class="example"><b>${U('Kya notice karna hai?','What to notice')}</b><p>${U('Invalid form count ho raha ho to click trigger ko success trigger se compare karo. Repeat se count barhay to deduplication try karo. Settings badalnay se purana log rewrite nahi hota; clean comparison ke liye reset karo.','If invalid forms are counted, compare click and success triggers. If repeats inflate counts, try deduplication. Settings do not rewrite existing logs; reset for a clean comparison.')}</p></div>${sourceLinks(['tagtest'])}</section></div>`;}
function mathProblems(){const b=biz(),cpc=b.cpc,spend=cpc*100,contribution=b.aov*b.margin/100;return [
 {id:'ctr',q:W('2,000 impressions se 100 clicks aaye. CTR kitna %?','2,000 impressions generated 100 clicks. What is CTR (%)?'),unit:'%',answer:5,working:'100 ÷ 2,000 × 100 = 5%',hint:W('Clicks ko impressions se divide karo, phir ×100.','Divide clicks by impressions, then multiply by 100.')},
 {id:'cpc',q:W(`${money(spend)} spend aur 100 clicks. Average CPC kitna?`,`${money(spend)} spend and 100 clicks. What is average CPC?`),unit:'Rs',answer:cpc,working:`${spend} ÷ 100 = ${cpc}`,hint:W('Spend ÷ clicks.','Spend ÷ clicks.')},
 {id:'cvr',q:W('100 clicks se 5 valid leads. Click-to-lead CVR kitna %?','100 clicks produced 5 valid leads. What is click-to-lead CVR (%)?'),unit:'%',answer:5,working:'5 ÷ 100 × 100 = 5%',hint:W('Leads ÷ clicks ×100.','Leads ÷ clicks ×100.')},
 {id:'cpl',q:W(`${money(spend)} spend se 5 leads. CPL kitna?`,`${money(spend)} spend produced 5 leads. What is CPL?`),unit:'Rs',answer:spend/5,working:`${spend} ÷ 5 = ${spend/5}`,hint:W('Spend ko lead count se divide karo.','Divide spend by lead count.')},
 {id:'close',q:W('20 qualified leads mein se 4 customers. Close rate kitna %?','4 of 20 qualified leads became customers. What is close rate (%)?'),unit:'%',answer:20,working:'4 ÷ 20 × 100 = 20%',hint:W('Customers ÷ leads ×100.','Customers ÷ leads ×100.')},
 {id:'cac',q:W('Rs 10,000 spend se 2 customers. Acquisition cost per customer?','Rs 10,000 spend produced 2 customers. What is cost per customer?'),unit:'Rs',answer:5000,working:'10,000 ÷ 2 = 5,000',hint:W('Spend ÷ customers. Lead cost aur customer cost alag hain.','Spend ÷ customers. Lead cost differs from customer cost.')},
 {id:'roas',q:W('Rs 30,000 revenue aur Rs 10,000 ad spend. ROAS kitna ×?','Rs 30,000 revenue and Rs 10,000 ad spend. What is ROAS (×)?'),unit:'×',answer:3,working:'30,000 ÷ 10,000 = 3×',hint:W('Revenue ÷ ad spend. Yahan percentage nahi, multiplier dalo.','Revenue ÷ ad spend. Enter a multiplier, not a percentage.')},
 {id:'profit',q:W('Rs 30,000 revenue, 25% contribution margin aur Rs 10,000 ad spend. Ads ke baad contribution?','Rs 30,000 revenue, 25% contribution margin and Rs 10,000 ad spend. What is contribution after ads?'),unit:'Rs',answer:-2500,working:'30,000 × 0.25 − 10,000 = −2,500',hint:W('Pehle margin wala contribution nikalo, phir ad spend subtract karo. Negative answer allowed hai.','Calculate contribution using margin, then subtract ad spend. Negative answers are allowed.')},
 {id:'breakroas',q:W('25% contribution margin par break-even revenue ROAS kitna ×?','At a 25% contribution margin, what is break-even revenue ROAS (×)?'),unit:'×',answer:4,working:'1 ÷ 0.25 = 4×',hint:W('1 ÷ margin fraction. Fixed overhead is simple model mein excluded hai.','1 ÷ margin fraction. Fixed overhead is excluded in this model.')},
 {id:'breaklead',q:W(`${money(b.aov)} revenue/customer, ${b.margin}% margin aur ${b.close}% close rate. Break-even CPL/order CPA?`,`${money(b.aov)} revenue/customer, ${b.margin}% margin and ${b.close}% close rate. What is break-even CPL/order CPA?`),unit:'Rs',answer:contribution*b.close/100,working:`${b.aov} × ${b.margin/100} × ${b.close/100} = ${num(contribution*b.close/100,2)}`,hint:W('Revenue/customer × margin fraction × close-rate fraction.','Revenue/customer × margin fraction × close-rate fraction.')},
 {id:'budget',q:W('Rs 30,400 unchanged full-month budget. Average daily budget?','Rs 30,400 unchanged full-month budget. What is the average daily budget?'),unit:'Rs',answer:1000,working:'30,400 ÷ 30.4 = 1,000',hint:W('Monthly amount ÷30.4. Ye simple planning model hai.','Monthly amount ÷30.4. This is a simple planning model.')},
 {id:'forecast',q:W('Rs 10,000 budget, Rs 100 CPC, 10% lead CVR aur 20% close rate. Expected customers?','Rs 10,000 budget, Rs 100 CPC, 10% lead CVR and 20% close rate. Expected customers?'),unit:'customers',answer:2,working:'(10,000 ÷ 100) × 0.10 × 0.20 = 2',hint:W('Clicks → leads → customers. Estimate hai, guarantee nahi.','Clicks → leads → customers. This is an estimate, not a guarantee.')}
 ];}
function checkMath(problem,raw){if(typeof raw!=='string'||!raw.trim())return{valid:false,correct:false};const cleaned=raw.trim().replace(/,/g,'');if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(cleaned))return{valid:false,correct:false};const value=Number(cleaned);return{valid:Number.isFinite(value),correct:Number.isFinite(value)&&Math.abs(value-problem.answer)<=.011};}
function mathView(){const ps=mathProblems(),solved=ps.filter(p=>state.maths[state.business+'/'+p.id]===true).length;return `<div class="section-heading"><h2>${U('Calculator se pehle khud try karo','Try it before the calculator')}</h2><span class="tag">${solved}/${ps.length} solved</span></div><p>${U('Sirf number dalo. Unit field ke saath likhi hai. Commas aur negative values allowed hain.','Enter a number only. Units are shown alongside the field. Commas and negative values are supported.')}</p><div class="cards">${ps.map((p,i)=>{const f=mathFeedback[state.business+'/'+p.id];return `<article class="card"><div class="eyebrow">DRILL ${String(i+1).padStart(2,'0')} ${state.maths[state.business+'/'+p.id]?'· SOLVED':''}</div><h3 style="line-height:1.7">${esc(t(p.q))}</h3><label class="field" style="margin-top:18px">${U('Tumhara answer','Your answer')} (${p.unit})<input type="text" inputmode="decimal" data-math-input="${p.id}" value="${esc(f?.raw||'')}" autocomplete="off"></label><button class="btn light" data-math-check="${p.id}">${U('Check karo','Check answer')}</button><details class="source-details"><summary>${U('Chhota hint','A small hint')}</summary><p>${esc(t(p.hint))}</p></details>${f?`<div class="feedback ${f.correct?'':'error'}" role="status">${!f.valid?U('Sirf valid number dalo; % ya Rs mat likho.','Enter a valid number without % or Rs.'):f.correct?`✓ ${U('Sahi! Working dekho:','Correct! Here is the working:')}<div class="formula">${esc(p.working)}</div>`:U('Abhi match nahi hua. Unit aur denominator check karke dobara try karo.','Not quite. Check the unit and denominator, then try again.')}</div>`:''}</article>`;}).join('')}</div>`;}
function bindWorkshop(){if(workshopTab==='case')bindCase();$('#workshop-business').onchange=e=>{state.business=e.target.value;save();render();};$$('[data-workshop-tab]').forEach(b=>b.onclick=()=>{workshopTab=b.dataset.workshopTab;render();});$$('[data-mission]').forEach(b=>b.onclick=()=>{missionId=b.dataset.mission;render();});$$('[data-mission-answer]').forEach(b=>b.onclick=()=>{const y=window.scrollY;missionRecord().answers[missionRecord().step]=+b.dataset.missionAnswer;save();render();window.scrollTo(0,y);});const back=$('#mission-back'),next=$('#mission-next');if(back)back.onclick=()=>{missionRecord().step=Math.max(0,missionRecord().step-1);save();render();};if(next)next.onclick=()=>{const m=MISSIONS.find(m=>m.id===missionId),r=missionRecord();if(r.answers[r.step]!==m.steps[r.step][3])return;if(r.step<m.steps.length-1){r.step++;save();render();}else{const complete=m.steps.every((s,i)=>r.answers[i]===s[3]);$('#mission-summary').innerHTML=`<div class="feedback ${complete?'':'error'}" style="margin-top:20px">${complete?U('Mission decisions complete! Ab related practice lab aur actual implementation guide use karo.','Mission decisions complete! Continue with the related practice lab and implementation guide.'):U('Kuch earlier steps abhi correct nahi. Back se revisit karo.','Some earlier steps are not yet correct. Go back and revisit them.')}</div>`;}};const trigger=$('#sim-trigger'),dedupe=$('#sim-dedupe');if(trigger)trigger.onchange=e=>{sim.trigger=e.target.value;render();};if(dedupe)dedupe.onchange=e=>{sim.dedupe=e.target.checked;render();};$$('[data-sim]').forEach(b=>b.onclick=()=>{const y=window.scrollY;trackingEvent(b.dataset.sim);render();window.scrollTo(0,y);});$$('[data-math-check]').forEach(b=>b.onclick=()=>{const p=mathProblems().find(p=>p.id===b.dataset.mathCheck),raw=document.querySelector(`[data-math-input="${p.id}"]`).value,result=checkMath(p,raw),key=state.business+'/'+p.id;mathFeedback[key]={...result,raw};if(result.correct)state.maths[key]=true;save();const y=window.scrollY;render();window.scrollTo(0,y);});}
function cleanMissions(value){const result={};if(!value||typeof value!=='object')return result;for(const b of BUSINESSES)for(const m of MISSIONS){const key=b.id+'/'+m.id,r=value[key];if(!r||typeof r!=='object')continue;result[key]={step:Number.isInteger(r.step)?Math.max(0,Math.min(m.steps.length-1,r.step)):0,answers:{}};for(let i=0;i<m.steps.length;i++){const a=r.answers?.[i];if(Number.isInteger(a)&&a>=0&&a<m.steps[i][2].length)result[key].answers[i]=a;}}return result;}
function cleanMaths(value){const result={};if(!value||typeof value!=='object')return result;const ids=['ctr','cpc','cvr','cpl','close','cac','roas','profit','breakroas','breaklead','budget','forecast'];for(const b of BUSINESSES)for(const id of ids)if(value[b.id+'/'+id]===true)result[b.id+'/'+id]=true;return result;}
function workshopLessonLink(chapter){const target=chapter===2?'tracking':chapter===7?'math':chapter===9||chapter===10?'optimize':chapter===4||chapter===8?'setup':null;return target?`<div class="workshop-banner compact"><div><div class="eyebrow">PRACTICE THIS CONCEPT</div><p>${U('Isi topic ko guided practice mein try karo.','Try this topic in guided practice.')}</p></div><button class="btn light" data-workshop-open="${target}">${U('Practice kholo','Open practice')} →</button></div>`:'';}
